    <div>Recebidos<span data-testid="sync-fetched">{{ sync_result.fetched }}</span></div>
    <div>Processados<span data-testid="sync-processed">{{ sync_result.processed }}</span></div>
    <div>Para revisão<span data-testid="sync-needs-review">{{ sync_result.needs_review }}</span></div>
    <div>Falhados<span data-testid="sync-failed">{{ sync_result.failed }}</span></div>
    <div>Ignorados<span data-testid="sync-skipped">{{ sync_result.skipped }}</span></div>
  </div>
