{% if orders %}
  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>#</th><th>Email</th><th>Cliente</th><th>Entrega</th>
          <th class="num">Linhas</th><th>Estado</th><th>Método</th>
        </tr>
      </thead>
      <tbody>
        {% for o in orders %}
        <tr>
          <td><a href="/ui/orders/{{ o.id }}">{{ o.id }}</a></td>
          <td>{{ o.source_email_id }}</td>
          <td>{{ o.customer_name or o.customer_email }}</td>
          <td>{{ o.requested_delivery_date or '—' }}</td>
          <td class="num">{{ o.lines | length }}</td>
          <td><span class="badge {{ o.status }}">{{ o.status }}</span></td>
          <td class="muted">{{ o.extraction_method }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
{% else %}
  <div class="card muted">Ainda não há encomendas. Carrega em “Sincronizar emails” para importar da API Ferrapex.</div>
{% endif %}
{% endblock %}
